import{_ as o,o as t,c as d,a3 as a}from"./chunks/framework.B8xISX-C.js";const f=JSON.parse('{"title":"Patch operations","description":"","frontmatter":{},"headers":[],"relativePath":"reference/patch-ops.md","filePath":"reference/patch-ops.md"}'),c={name:"reference/patch-ops.md"};function r(s,e,n,l,i,h){return t(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="patch-operations" tabindex="-1">Patch operations <a class="header-anchor" href="#patch-operations" aria-label="Permalink to &quot;Patch operations&quot;">​</a></h1><p>A patch file is <code>patches/&lt;file&gt;.json</code>: <code>{ &quot;$schema&quot;: &quot;carina-patch/1&quot;, &quot;patches&quot;: [ ...rows ] }</code>. Rows apply in package order, files in path order, rows in file order. Every row names <code>op</code>, <code>catalog</code> and <code>key</code>; a path is dot-separated property names (at most 8), never a list index; the segment after a keyed array names an element by its key (<code>levels.advanced.alsoKnown</code>).</p><table tabindex="0"><thead><tr><th>Op</th><th>Fields</th><th>Does</th></tr></thead><tbody><tr><td><code>set</code></td><td><code>path</code>, <code>value</code></td><td>replaces the value at <code>path</code> (or creates an absent last field); a non-null old value keeps its JSON kind</td></tr><tr><td><code>append</code></td><td><code>path</code>, <code>value</code></td><td>adds <code>value</code> at the end of the list at <code>path</code></td></tr><tr><td><code>insertAfter</code></td><td><code>path</code>, <code>after</code>, <code>value</code></td><td>inserts <code>value</code> after the first element equal to <code>after</code></td></tr><tr><td><code>removeValue</code></td><td><code>path</code>, <code>value</code></td><td>removes every element equal to <code>value</code></td></tr><tr><td><code>remove</code></td><td></td><td>removes the record (open catalogs only)</td></tr><tr><td><code>splice</code></td><td><code>after</code></td><td>links an unlinked tech field (<code>key</code>) into a research chain after the field <code>after</code></td></tr></tbody></table><p>Ops: <code>set</code>, <code>append</code>, <code>insertAfter</code>, <code>removeValue</code>, <code>remove</code>, <code>splice</code>.</p><p>Every row may also carry:</p><ul><li><code>expect</code>: record paths and the values they must hold first, for example <code>{ &quot;cost&quot;: 7 }</code>. When the game changes that value, the row fails with <code>patch-expect-failed</code> naming the new value, instead of silently changing something else.</li><li><code>optional: true</code>: a missing record, path, anchor or value is skipped (reported as <code>patch-skipped</code>) instead of failing with <code>patch-no-match</code>.</li></ul><h2 id="special-catalogs" tabindex="-1">Special catalogs <a class="header-anchor" href="#special-catalogs" aria-label="Permalink to &quot;Special catalogs&quot;">​</a></h2><ul><li><code>profile</code> (key: the profile id): only <code>availableRaces</code> and <code>flags</code> are open to mods.</li><li><code>provisional</code> (key: the constant&#39;s name): <code>set</code> with path <code>value</code> only; constants are never added or removed.</li><li>Protected everywhere: a record&#39;s <code>id</code>, <code>key</code> and <code>prov</code>.</li></ul><h2 id="conflicts" tabindex="-1">Conflicts <a class="header-anchor" href="#conflicts" aria-label="Permalink to &quot;Conflicts&quot;">​</a></h2><p>Two mods with no load order between them that both <code>set</code> the same path (or one removes a record the other changes) conflict: the player picks the winner for the game. List operations (<code>append</code>, <code>insertAfter</code>, <code>removeValue</code>) from several mods combine. Declare <code>loadAfter</code> or a dependency in <code>mod.json</code> when your mod builds on another.</p>',10)])])}const m=o(c,[["render",r]]);export{f as __pageData,m as default};
